/**
 * The Rust↔TypeScript contract, derived from the Rust sources.
 *
 * `src/testdata/contract/rust-structs.json` is machine-generated by
 * `regenerate.mjs` from `core/src/**` and `apps/desktop/src-tauri/**`. This
 * module loads it, turns it into a checkable spec and records the *known*
 * differences between the Rust wire format and the TypeScript mirror in
 * `src/state/types.ts`.
 *
 * Nothing in here reads the TypeScript types to decide what the wire format
 * is — the Rust side is the source of truth. The TypeScript side is only
 * ever checked *against* it.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));

/** Repo root — `apps/web/src/contract` is four levels below it. */
export const REPO_ROOT = join(HERE, "..", "..", "..", "..");
/** `apps/web/src`. */
export const WEB_SRC = join(HERE, "..");
/** `apps/web/src/testdata/contract`. */
export const FIXTURE_DIR = join(WEB_SRC, "testdata", "contract");

export interface RustField {
  /** The field name as written in Rust (`course_id`). */
  rustName: string;
  /** The key the field has on the wire (`course_id`, `date_iso`, `type`). */
  wireName: string;
  /** The raw Rust type (`String`, `Option<f64>`, `Vec<Course>`, …). */
  rustType: string;
  /** True when the Rust type is `Option<…>` (nullable on the wire). */
  optional: boolean;
}

export interface RustStruct {
  source: string;
  fields: RustField[];
}

export interface RustVariant {
  name: string;
  wireName: string;
}

export interface RustEnum {
  source: string;
  variants: RustVariant[];
}

export interface FfiExport {
  parameters: string[];
  returns: string;
}

export interface RustContract {
  generatedBy: string;
  note: string;
  sourceFiles: string[];
  sourceHashes: Record<string, string>;
  structs: Record<string, RustStruct>;
  enums: Record<string, RustEnum>;
  enumLabels: Record<string, string[]>;
  ffiExports: Record<string, FfiExport>;
}

function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, "utf8")) as T;
}

/** The machine-derived map of the Rust wire format. */
export const RUST_CONTRACT: RustContract = readJson<RustContract>(
  join(FIXTURE_DIR, "rust-structs.json"),
);

// ---------------------------------------------------------------------------
// Enum sets — read straight off the Rust source.
// ---------------------------------------------------------------------------

/** The labels `AssessmentType` serializes to (`#[serde(rename = "…")]`). */
export const RUST_ASSESSMENT_TYPES: string[] = RUST_CONTRACT.enumLabels.AssessmentType;

/**
 * The labels `AssessmentSource` serializes to (its hand-written
 * `Serialize`/`as_str`). A source outside this set is a user feed label —
 * `AssessmentSource::Feed(name)` — and is legal on the wire.
 */
export const RUST_ASSESSMENT_SOURCE_LABELS: string[] = RUST_CONTRACT.enumLabels.AssessmentSource;

/**
 * The urgency labels the core *emits* — serde `rename_all = "lowercase"`
 * (added when the emit/store shapes were unified), so the wire is the
 * lower-case ladder.
 */
export const RUST_URGENCY_EMIT_LABELS: string[] = RUST_CONTRACT.enums.UrgencyLevel.variants.map(
  (variant) => variant.wireName,
);

/**
 * The urgency labels the core *stores* (`store/repo.rs::urgency_label`) and
 * accepts on import (`UrgencyLevel::deserialize` lower-cases the label).
 */
export const RUST_URGENCY_STORED_LABELS: string[] = RUST_CONTRACT.enumLabels.UrgencyLevelStored;

/** The conflict severities the core emits. */
export const RUST_CONFLICT_SEVERITIES: string[] = RUST_CONTRACT.enums.ConflictSeverity.variants.map(
  (variant) => variant.wireName,
);

