export interface KnownFieldGap {
  rustStruct: string;
  /** The Rust wire name the TypeScript mirror never exposes. */
  rustField: string;
  tsInterface: string;
  reason: string;
}

/**
 * Rust fields the TypeScript mirror does not declare. These are real
 * divergences — the payload carries the value, `src/state/types.ts` does not
 * describe it. The list is asserted exactly, so a field that gets fixed
 * (or a new one that appears) fails the suite until this list is updated.
 *
 * It is currently EMPTY: the contract test found every gap the v5 shell had
 * (the recommendation card's date/time/badge/rules, the conflict alert's
 * ids and gap hours, the roadmap task's title and reasoning) and each one
 * was closed on both sides — the mirror declares the field and the adapter
 * fills the name the views read.
 */
export const KNOWN_FIELD_GAPS: KnownFieldGap[] = [];

export interface KnownTsOnlyField {
  tsInterface: string;
  tsField: string;
  reason: string;
}

