export interface KnownEnumDivergence {
  id: string;
  /** The labels the Rust core actually emits. */
  rustEmit: string[];
  /** The labels the TypeScript mirror declares. */
  tsDeclared: string[];
  impact: string;
}

/**
 * Enum sets where the Rust core and the TypeScript mirror disagree. The
 * contract test asserts these entries against the live Rust source and the
 * live TypeScript types, so a fix on either side fails the suite until this
 * record is updated — a divergence can never rot silently.
 */
export const KNOWN_ENUM_DIVERGENCES: KnownEnumDivergence[] = [];

// ---------------------------------------------------------------------------
// The TypeScript mirror — parsed, never hand-copied.
// ---------------------------------------------------------------------------

export interface TsField {
  name: string;
  /** The property is declared optional (`name?: T`). */
  optional: boolean;
  /** The declared type admits `null` (`T | null`). */
  nullable: boolean;
  typeText: string;
}

/**
 * Parse the `export interface` blocks of a TypeScript source file.
 *
 * Only what the contract needs: the property names, whether they are
 * optional and whether their type admits `null`.
 */
export function parseTsInterfaces(source: string): Record<string, Record<string, TsField>> {
  const interfaces: Record<string, Record<string, TsField>> = {};
  const lines = source.split(/\r?\n/);

  for (let index = 0; index < lines.length; index += 1) {
    const declaration = /^export\s+interface\s+([A-Za-z_][A-Za-z0-9_]*)\s*\{/.exec(lines[index]);
    if (!declaration) {
      continue;
    }
    const name = declaration[1];
    const fields: Record<string, TsField> = {};
    for (let scan = index + 1; scan < lines.length; scan += 1) {
      const line = lines[scan].trim();
      if (line === "}") {
        break;
      }
      const property = /^([A-Za-z_][A-Za-z0-9_]*)(\?)?\s*:\s*(.+?);$/.exec(line);
      if (!property) {
        continue;
      }
      const typeText = property[3].trim();
      fields[property[1]] = {
        name: property[1],
        optional: property[2] === "?",
        nullable: /\|\s*null\b/.test(typeText),
        typeText,
      };
    }
    interfaces[name] = fields;
    index += 1;
  }

  return interfaces;
}

/** `course_id` → `courseId`. */
export function camelCase(name: string): string {
  return name.replace(/_([a-z0-9])/g, (_match, chr: string) => chr.toUpperCase());
}
